   "register": "tu",
   "anker": "söylemek",
   "notiz": "şarkı = Lied; şarkı söylemek = singen (wörtlich: Lied sagen). Vokal e fällt vor -iyor: söyle- → söyl-üyor, dinle- → dinl-iyor. « da/de » nach dem Wort = auch.",
