   "register": "tu",
   "anker": "olmak",
   "notiz": "aslında = eigentlich, in Wahrheit (asıl = Ursprung, echt). şu anda = im Moment (an = Augenblick). Prädikative Personalendung: yorgun-um, iyi-yim.",
