    "luecke": "Kitapçıya",
    "gloss": "Kitap·çı·ya git·ti·m, kütüphane·ye değil; para·yı ora·da bırak·tı·m. | Buch·Täter·DAT gehen·VERG·1SG, Bibliothek·DAT nicht; Geld·AKK dort·LOK lassen·VERG·1SG",
