     "de": "Heute haben wir gewonnen, morgen werden wir sehen.",
     "gloss": "Bugün kazan·dı·k, yarın gör·eceğ·iz. | heute gewinnen·VERG·1PL, morgen sehen·FUT·1PL",
     "umschrift": null,
     "audio": "audio/tr-de/saetze/sp_16.mp3?v=94e109df",
